<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { Edit3, Plus, RefreshCw, Trash2 } from 'lucide-vue-next'
import { api, apiError } from '../api/client'
import type { ApiResponse } from '../types'
import PageHeader from '../components/PageHeader.vue'
import DrawerPanel from '../components/DrawerPanel.vue'
import InlineAlert from '../components/InlineAlert.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EmptyState from '../components/EmptyState.vue'
import { permissionGroup, permissionLabel, roleLabel } from '../utils/labels'

interface Role{id:string;code:string;name:string;description?:string;permissions:string[];is_system:boolean;is_active:boolean;created_at:string}
const items=ref<Role[]>([]),presets=ref<Record<string,string[]>>({}),drawer=ref(false),editing=ref<Role|null>(null),error=ref(''),success=ref('')
const form=reactive({code:'',name:'',description:'',permissions:[] as string[],is_active:true})
const allPermissions=computed(()=>Array.from(new Set([...Object.values(presets.value).flat(),...items.value.flatMap(x=>x.permissions)])).sort())
const permissionGroups=computed(()=>{const groups:Record<string,string[]>={};for(const permission of allPermissions.value){const group=permissionGroup(permission);(groups[group]??=[]).push(permission)}return groups})
const makeCode=(name:string)=>name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,64)||`PERFIL_${Date.now()}`
async function load(){error.value='';try{const [r,p]=await Promise.all([api.get<ApiResponse<Role[]>>('/v1/roles'),api.get<ApiResponse<Record<string,string[]>>>('/v1/role-presets')]);items.value=r.data.data;presets.value=p.data.data}catch(e){error.value=apiError(e)}}
function open(item?:Role){editing.value=item||null;Object.assign(form,item?{code:item.code,name:item.name,description:item.description||'',permissions:[...item.permissions],is_active:item.is_active}:{code:'',name:'',description:'',permissions:[],is_active:true});drawer.value=true}
function applyPreset(code:string){form.permissions=[...(presets.value[code]||[])];if(!editing.value){form.name=roleLabel(code);form.code=code}}
async function save(){error.value='';try{if(!form.code)form.code=makeCode(form.name);const payload={code:form.code,name:form.name,description:form.description||null,permissions:[...form.permissions],is_active:form.is_active};if(editing.value)await api.patch(`/v1/roles/${editing.value.id}`,payload);else await api.post('/v1/roles',payload);drawer.value=false;success.value='Perfil salvo.';await load()}catch(e){error.value=apiError(e)}}
async function remove(item:Role){if(!confirm(`${item.is_system?'Desativar':'Excluir'} ${item.name}?`))return;try{await api.delete(`/v1/roles/${item.id}`);await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="Perfis e permissões" subtitle="Defina com clareza o que cada perfil pode consultar, cadastrar, editar e administrar."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-primary" @click="open()"><Plus :size="18"/>Novo perfil</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><div class="grid gap-5 xl:grid-cols-2"><article v-for="item in items" :key="item.id" class="card"><div class="flex items-start gap-3"><div class="flex-1"><div class="flex flex-wrap items-center gap-2"><h2 class="font-bold">{{item.name}}</h2><span v-if="item.is_system" class="badge bg-violet-50 text-violet-700">Perfil padrão</span><StatusBadge :status="item.is_active?'ACTIVE':'INACTIVE'"/></div><p class="mt-2 text-sm text-slate-500">{{item.description||'Perfil de acesso configurado para esta operação.'}}</p></div><button class="btn-secondary px-3 py-2" title="Editar perfil" @click="open(item)"><Edit3 :size="16"/></button><button class="btn-secondary px-3 py-2 text-rose-600" :title="item.is_system?'Desativar perfil':'Excluir perfil'" @click="remove(item)"><Trash2 :size="16"/></button></div><div class="scroll-clean mt-4 flex max-h-32 flex-wrap gap-1 overflow-auto"><span v-for="permission in item.permissions" :key="permission" class="badge bg-teal-50 text-teal-700">{{permissionLabel(permission)}}</span></div></article><EmptyState v-if="!items.length" title="Nenhum perfil cadastrado"/></div><DrawerPanel :open="drawer" :title="editing?'Editar perfil':'Novo perfil'" width="xl" @close="drawer=false"><form class="space-y-5" @submit.prevent="save"><div class="grid gap-4 md:grid-cols-2"><div><label class="label">Nome do perfil</label><input v-model="form.name" class="input" placeholder="Ex.: Assistente financeiro" required/></div><label class="flex items-center gap-2 pt-8 text-sm"><input v-model="form.is_active" type="checkbox"/> Perfil ativo</label></div><div><label class="label">Descrição</label><textarea v-model="form.description" class="input" rows="2" placeholder="Explique em linguagem simples para que este perfil será usado."/></div><div v-if="!editing" class="rounded-xl border border-slate-200 p-4"><p class="font-semibold text-slate-700">Começar por um perfil sugerido</p><p class="mt-1 text-sm text-slate-500">Você pode escolher uma base e depois marcar ou desmarcar permissões.</p><div class="mt-3 flex flex-wrap gap-2"><button v-for="(_,code) in presets" :key="String(code)" type="button" class="btn-secondary px-3 py-2" @click="applyPreset(String(code))">{{roleLabel(String(code))}}</button></div></div><div><div class="mb-3 flex items-center justify-between"><div><p class="font-semibold text-slate-700">Permissões do perfil</p><p class="text-sm text-slate-500">Selecione somente o necessário para a função.</p></div><span class="badge bg-slate-100 text-slate-600">{{form.permissions.length}} selecionadas</span></div><div class="scroll-clean max-h-[32rem] space-y-5 overflow-auto rounded-xl border border-slate-200 p-4"><section v-for="(permissions,group) in permissionGroups" :key="group"><h3 class="mb-2 text-xs font-bold uppercase tracking-wide text-slate-500">{{group}}</h3><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-3"><label v-for="permission in permissions" :key="permission" class="flex items-start gap-2 rounded-lg p-2 text-sm hover:bg-slate-50"><input v-model="form.permissions" class="mt-0.5" type="checkbox" :value="permission"/><span>{{permissionLabel(permission)}}</span></label></div></section></div></div><details v-if="!editing?.is_system" class="rounded-xl border border-slate-200 p-4"><summary class="cursor-pointer text-sm font-semibold text-slate-600">Opções avançadas</summary><div class="mt-3"><label class="label">Identificador interno do perfil</label><input v-model="form.code" class="input uppercase" placeholder="Gerado automaticamente"/></div></details><div class="flex justify-end gap-2 border-t pt-4"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary">Salvar perfil</button></div></form></DrawerPanel></template>
